import { test, expect } from '@playwright/test';

test.describe('Product Search by Keyword - Instant Results', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/products');
  });

  test('should display instant search results when user enters a valid keyword', async ({ page }) => {
    // Setup: intercept the search API call
    await page.route('**/api/products/search', (route) => {
      route.continue();
    });

    // Verify search input exists
    const searchInput = page.getByPlaceholder('Search products...');
    await expect(searchInput).toBeVisible();

    // Verify search button exists
    const searchButton = page.getByRole('button', { name: /search/i });
    await expect(searchButton).toBeVisible();

    // Verify search results container exists
    const searchResultsContainer = page.getByRole('region', { name: /search results/i });
    await expect(searchResultsContainer).toBeVisible();

    // Verify no results are displayed initially
    const resultCount = page.getByText('0 results');
    await expect(resultCount).toBeVisible();

    // Enter a valid keyword and trigger search
    await searchInput.fill('laptop');
    await searchButton.click();

    // Wait for search results to load
    await page.waitForTimeout(500);

    // Verify results are displayed
    const resultCount = page.getByText('1 result');
    await expect(resultCount).toBeVisible();

    // Verify result item is visible
    const resultItem = page.getByText('Dell Latitude 7410 Laptop');
    await expect(resultItem).toBeVisible();

    // Verify result item has correct details
    const resultTitle = page.getByText('Dell Latitude 7410 Laptop');
    await expect(resultTitle).toBeVisible();

    const resultPrice = page.getByText('$999');
    await expect(resultPrice).toBeVisible();

    // Verify result item has a clickable link
    const resultLink = page.getByRole('link', { name: /laptop/i });
    await expect(resultLink).toBeVisible();

    // Verify search results container has correct count
    const resultCountText = page.getByText('1 result');
    await expect(resultCountText).toBeVisible();
  });

